package bd.hscsolution.security;
import com.fasterxml.jackson.databind.ObjectMapper; import java.util.Map; import java.util.UUID; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.context.request.RequestContextHolder; import org.springframework.web.context.request.ServletRequestAttributes;
@Service public class AuditService{private final JdbcTemplate db; private final ObjectMapper mapper; public AuditService(JdbcTemplate db,ObjectMapper mapper){this.db=db;this.mapper=mapper;}
 public void record(UUID actor,String action,String entityType,UUID entityId,Map<String,Object> before,Map<String,Object> after){try{String correlation=null;var a=RequestContextHolder.getRequestAttributes();if(a instanceof ServletRequestAttributes s) correlation=s.getRequest().getHeader("X-Correlation-Id");db.update("insert into audit_log(actor_user_id,action,entity_type,entity_id,correlation_id,before_data,after_data) values(?,?,?,?,?,?::jsonb,?::jsonb)",actor,action,entityType,entityId,correlation,before==null?null:mapper.writeValueAsString(before),after==null?null:mapper.writeValueAsString(after));}catch(Exception ignored){}}
}
